<?php
namespace App\Http\Controllers;
use App\Models\Ticket; use Endroid\QrCode\QrCode; use Endroid\QrCode\Writer\PngWriter; use Illuminate\Http\Response; use Illuminate\Http\Request;
class TicketController extends Controller { public function qr(Request $request,Ticket $ticket):Response{$ticket->load('order.show.event','order.user','seat');$allowed=$request->user() && ($request->user()->id===$ticket->order->user_id || $request->user()->hasAnyRole(['مدیر سیستم','مدیر فروش','اپراتور گیشه']));abort_unless($allowed,403);$png=(new PngWriter())->write(QrCode::create(json_encode(['ticket'=>$ticket->code,'event'=>$ticket->order->show->event->title],JSON_UNESCAPED_UNICODE))->setSize(360)->setMargin(12))->getString();return response($png,200,['Content-Type'=>'image/png','Cache-Control'=>'private, no-store']);} public function checkin(Ticket $ticket){abort_if($ticket->status!=='valid',422,'این بلیت قابل استفاده نیست.');$ticket->update(['status'=>'used','checked_in_at'=>now()]);return response()->json(['ok'=>true,'ticket'=>$ticket->code]);} }
